    round.pendingPayout = amount;
    this.#store.save(round);
    const balance: number = yield { kind: 'payout', txId: `${round.roundId}:payout`, roundId: round.roundId, amount };
    round.status = 'closed';
    round.payout = amount;
    round.pendingPayout = null;
    this.#store.save(round);
    return balance;
  }

